// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;

    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(bytes4 fuzzedId) public {
        bytes4 metadataId = bytes4(0x0e89341c); // IERC1155MetadataURI.interfaceId
        bool ok;
        try c.supportsInterface(metadataId) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }
        assertTrue(ok, "supportsInterface must accept the ERC1155MetadataURI interface id");
        // general rule: for every fuzzed id the metadata id is always accepted
    }
}
